import{_ as a,c as n,o as t,ag as s}from"./chunks/framework.Bzez9NG9.js";const o="/space/img/space_overview.png",i="/space/img/space_platform.png",m=JSON.parse('{"title":"Getting started","description":"Overview of SPACE for IBM Planning Analytics, including AI, model analysis, Python, logs, lifecycle management, security, connections, and deployment.","frontmatter":{"title":"Getting started","description":"Overview of SPACE for IBM Planning Analytics, including AI, model analysis, Python, logs, lifecycle management, security, connections, and deployment.","keywords":["IBM Planning Analytics","TM1","PAW","Planning Analytics Workspace","SPACE overview","onboarding"],"outline":"deep"},"headers":[],"relativePath":"doc/index.md","filePath":"doc/index.md"}'),r={name:"doc/index.md"};function c(l,e,d,p,u,g){return t(),n("div",null,e[0]||(e[0]=[s('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="what-is-space" tabindex="-1">What is SPACE? <a class="header-anchor" href="#what-is-space" aria-label="Permalink to &quot;What is SPACE?&quot;">​</a></h2><p>The Succeedium Planning Analytics Cloud Extension (SPACE) is an AI-powered platform for IBM Planning Analytics that brings analysis, development, automation, and lifecycle management into a single environment.</p><p>SPACE can be used directly inside IBM Planning Analytics Workspace (PAW) or through its standalone web application. Business users can explore models and data with natural language, while developers and administrators can work with model objects, Python, automation, logs, Git, releases, security, and environment operations.</p><p><img src="'+o+'" alt="SPACE overview" data-zoomable=""></p><h2 id="ai-across-space" tabindex="-1">AI across SPACE <a class="header-anchor" href="#ai-across-space" aria-label="Permalink to &quot;AI across SPACE&quot;">​</a></h2><p>SPACE AI provides a common, task-oriented interface across the platform. Instead of first deciding which module or tool to use, start with a question, request, or investigation.</p><p>Business users can use natural language to understand Planning Analytics models, explore and analyze data, and investigate variances. Developers and administrators can use the same interface to understand model logic, investigate issues and logs, work with Python, and perform supported development and operational tasks.</p><p>Where supported, SPACE AI can use SPACE-controlled tools and configured connections to carry out the required steps while respecting SPACE access controls and IBM Planning Analytics permissions.</p><p>Review the assistant&#39;s assumptions and results before relying on them for business decisions. See the <a href="/space/doc/ai/">AI Assistant guide</a> for more about SPACE AI capabilities, model-aware assistance, connected data, and governed access.</p><h2 id="space-platform" tabindex="-1">SPACE platform <a class="header-anchor" href="#space-platform" aria-label="Permalink to &quot;SPACE platform&quot;">​</a></h2><p>SPACE brings together model understanding, data analysis, development, administration, and lifecycle management in one platform. Its modules share common connections, security, and permissions, while teams can use the capabilities relevant to their work.</p><p><img src="'+i+'" alt="SPACE platform" data-zoomable=""></p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>If you are new to SPACE, start with the area that matches what you want to do:</p><ul><li><strong><a href="/space/doc/ai/">Use SPACE AI</a></strong> - Ask questions about Planning Analytics models and data, understand model logic, analyze connected data, or investigate an issue.</li><li><strong><a href="/space/doc/planning-analytics/model-documentation.html">Understand a Planning Analytics model</a></strong> - Use Model documentation to visualize cubes, dimensions, rules, processes, and their dependencies. Use <a href="/space/doc/planning-analytics/model-search.html">Model search</a> to find model objects and logic.</li><li><strong><a href="/space/doc/python/">Work with Python</a></strong> - Create Python scripts, use Jupyter notebooks, install custom packages, access configured connections and secrets, use TM1py, and build integrations and automation.</li><li><strong><a href="/space/doc/planning-analytics/users-and-access.html">Investigate TM1 access</a></strong> - Use Users and access to understand and troubleshoot why a user can or cannot access specific TM1 objects or data.</li><li><strong><a href="/space/doc/planning-analytics/logs.html">Investigate TM1 logs</a></strong> - Search IBM Planning Analytics audit, transaction, and server logs to investigate activity and issues.</li><li><strong><a href="/space/doc/planning-analytics/releases-and-deployments.html">Manage releases and deployments</a></strong> - Compare environments, organize changes into releases, and promote Planning Analytics objects between environments.</li><li><strong><a href="/space/doc/planning-analytics/git.html">Use TM1 Git</a></strong> - Link TM1 models to Git repositories for version control, collaboration, and change history.</li><li><strong><a href="/space/doc/configuration/">Configure SPACE</a></strong> - Manage connections, access, content, AI configuration, jobs, journal, and server settings.</li></ul><p>For source control of Python project files and Jupyter notebooks, see <a href="./python/git.html">Git for Python</a>.</p><h2 id="connections-and-security" tabindex="-1">Connections and security <a class="header-anchor" href="#connections-and-security" aria-label="Permalink to &quot;Connections and security&quot;">​</a></h2><p>A single SPACE instance can connect to multiple IBM Planning Analytics environments, including IBM PA Local, IBM PA Cloud, and IBM PA as a Service, as well as supported external data sources such as Google BigQuery.</p><p>SPACE supports SSO for IBM Planning Analytics and Google BigQuery, allowing users to connect with their own identity and access data according to their existing source-system permissions without providing their credentials to SPACE.</p><p>SPACE roles and connection access determine which capabilities and connections users can use. Native IBM Planning Analytics authentication and permissions continue to apply when accessing TM1; SPACE does not replace or bypass TM1 security.</p><p>SPACE also provides its own access controls for platform capabilities. Service-account credentials can be configured separately for supported non-interactive scenarios such as scheduled jobs.</p><p>See the <a href="/space/doc/configuration/">Configuration guide</a> for connection and SPACE access settings and <a href="/space/doc/planning-analytics/users-and-access.html">Users and access</a> for analyzing and troubleshooting TM1 user access.</p><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>SPACE is containerized and can be deployed on AWS, Microsoft Azure, Google Cloud Platform, IBM Cloud, or on-premises. Succeedium provides an environment-specific welcome kit covering prerequisites, deployment, authentication, and onboarding.</p>',25)]))}const y=a(r,[["render",c]]);export{m as __pageData,y as default};
